from cyhole.solana_fm import SolanaFM

def main() -> None:
    account = "AqU1KV9NEnNBWyveDbXtLdcAM7L2FE4NUvyxKPGGw45G"

    # api_key is read automatically from the SOLANA_FM_API_KEY env variable
    solana_fm = SolanaFM()

    response = solana_fm.client.get_account_transfers(account)

    for result in response.results:
        print(f"Transaction: {result.transaction_hash}")
        for transfer in result.data:
            print(
                f"  action={transfer.action} token={transfer.token} "
                f"amount={transfer.amount} source={transfer.source} "
                f"destination={transfer.destination}"
            )

if __name__ == "__main__":
    main()
